CREATE OR REPLACE PACKAGE stat_diff AS
  FUNCTION snapshot RETURN JSON;
  FUNCTION report(p_before IN JSON, p_after IN JSON) RETURN VARCHAR2;
  PROCEDURE around(p_query IN VARCHAR2);
END stat_diff;
